        "Vormen: strömt aus, strömte aus. Als iets uitstroomt en er beweging is, is het hulpwerkwoord in de voltooide tijd sein: Das Gas ist ausgeströmt. Met een lijdend voorwerp in de accusatief (Ruhe ausströmen) gebruik je haben: Sie hat Ruhe ausgeströmt.",
