        "Vormen: bebaut, bebaute, hat bebaut. Het deelwoord bebaut wordt vaak als bijvoeglijk naamwoord gebruikt: dicht bebaut (dicht bebouwd), unbebaut (onbebouwd). Voor gebouwen zeg je mit Häusern bebauen.",
