        "Vormen: begnügt sich, begnügte sich, hat sich begnügt. Het voorvoegsel be- is onscheidbaar, daarom geen ge-.",
        "Na mit volgt een zelfstandig naamwoord of voornaamwoord (damit), of een infinitiefgroep: sich damit begnügen, etwas zu tun (er genoegen mee nemen iets te doen)."
