        "De reden waarover iemand verontwaardigd is, geef je aan met über + accusatief: sich über die Frechheit entrüsten. Vormen: entrüstet sich, entrüstete sich, hat sich entrüstet. Het bijvoeglijk naamwoord entrüstet betekent verontwaardigd.",
