      "translation": "opzicht",
      "explanation": [
        "Kern: die Hinsicht is een vrouwelijk zelfstandig naamwoord dat een aspect of gezichtspunt aanduidt: in welk opzicht iets geldt. Het komt overeen met het Nederlandse 'opzicht' in verbindingen als in dit opzicht, in zeker opzicht.",
        "Meestal gebruikt in verbindingen met een voorzetsel: in dieser Hinsicht (in dit opzicht), in gewisser Hinsicht (in zeker opzicht), in jeder Hinsicht (in elk opzicht). Het meervoud die Hinsichten is zeldzaam. Formeel zegt men ook in Hinsicht auf + accusatief (met betrekking tot) of hinsichtlich + genitief."
      ],
      "examples": [
        {
          "de": "In dieser Hinsicht hast du recht.",
          "lv": "In dit opzicht heb je gelijk."
        },
        {
          "de": "In gewisser Hinsicht ist das ein Vorteil.",
          "lv": "In zeker opzicht is dat een voordeel."
        },
        {
          "de": "Das Hotel war in jeder Hinsicht perfekt.",
          "lv": "Het hotel was in elk opzicht perfect."
        },
        {
          "de": "In Hinsicht auf die Kosten gibt es noch Fragen.",
          "lv": "Met betrekking tot de kosten zijn er nog vragen."
        }
      ],
      "comparison": [
        {
          "word": "die Nachricht",
          "meaning": "bericht, nieuws",
          "example": "Ich habe eine Nachricht bekommen. – Ik heb een bericht gekregen."
        },
        {
          "word": "der Bezug",
          "meaning": "betrekking",
          "example": "In Bezug auf den Termin gibt es Fragen. – Met betrekking tot de afspraak zijn er vragen."
        },
        {
          "word": "die Rücksicht",
          "meaning": "consideratie",
          "example": "Er nimmt Rücksicht auf andere. – Hij houdt rekening met anderen."
        }
      ],
      "tip": [
        "Leer het als vaste uitdrukking: in dieser Hinsicht, in jeder Hinsicht.",
        "Na in volgt in deze verbindingen een datief: in dieser Hinsicht, in jeder Hinsicht."
      ],
      "important": [
        "Hinsicht betekent alleen 'opzicht'; een bericht of nieuws is Nachricht of Information.",
        "Na hinsichtlich (met betrekking tot) volgt een genitief: hinsichtlich der Kosten."
      ],
