        "Sterk werkwoord: er bietet, bot, hat geboten. Meestal met een accusatief, en de persoon in de datief: jemandem etwas bieten. Bij een bod op een veiling of bij een aankoop: Wie viel bietest du? (hoeveel bied je?)",
