        "Scheidbaar werkwoord: er bietet an, bot an, hat angeboten. Constructie: jemandem etwas anbieten. Met een infinitief: Er bot an, mich zu fahren (hij bood aan me te brengen). Wederkerend betekent sich anbieten zich aandienen, voor de hand liggen: Das bietet sich an.",
        "Het zelfstandig naamwoord is das Angebot (aanbod)."
