        "Regelmatig werkwoord: er fordert, forderte, hat gefordert. Wat iemand eist, staat in de accusatief, van wie, geef je aan met von + datief: etwas von jemandem fordern. Er kan ook een dass-zin volgen. Figuurlijk kan fordern ook slachtoffers eisen betekenen: Der Unfall forderte zwei Todesopfer.",
        "Let op het verwante woord: fordern (eisen) en fördern (bevorderen) verschillen alleen door de umlaut."
