        "Wederkerend werkwoord: ich verlaufe mich, er verläuft sich, verlief sich, hat sich verlaufen. De voltooide tijd (Perfekt) wordt met haben gevormd. Meestal staat er een plaats bij: im Wald, in der Stadt, in den Bergen.",
